-- Q2042: Fix #9
UPDATE questions SET
  stem = $EXPL$Rayburn Corp. spent $2,400,000 developing a new pharmaceutical compound: $1,600,000 before FDA approval and $800,000 after FDA approval for production ramp-up and packaging design., how much should be expensed as R&D?$EXPL$
