-- Q3214: Fix #9
UPDATE questions SET
  stem = $EXPL$A company has a derivative asset with a fair value of $50,000 at year-end., where is this derivative reported on the balance sheet?$EXPL$,
  explanation = $EXPL$All derivatives are recognized on the balance sheet at fair value. They are classified as current or noncurrent based on the expected settlement or maturity date. A derivative with a positive fair value is an asset; negative fair value is a liability. Classification follows the same principles as other financial assets/liabilities. (See ASC 815.)$EXPL$
