-- Q3241: Fix #9
UPDATE questions SET
  stem = $EXPL$A CPA is reviewing the government-wide statement of activities and notes that expenses are organized by department rather than by object., the statement of activities uses which format to present expenses?$EXPL$,
  explanation = $EXPL$The government-wide statement of activities presents expenses by function or program (public safety, education, highways, health, etc.), not by natural classification. This functional format, combined with the net cost presentation (expenses minus program revenues), shows taxpayers the net cost of each government service. (See GASB 34.)$EXPL$
WHERE id = 3241;

