-- Q3244: Fix #9
UPDATE questions SET
  stem = $EXPL$A CPA candidate is studying how component units are integrated into the primary government's financial statements., blended component units are presented in the financial statements as:$EXPL$,
  explanation = $EXPL$Blended component units are so closely related to the primary government that their funds are presented as if they are part of the primary government. Blending is required when the component unit's governing body is substantively the same as the primary government, or when the unit provides services exclusively to the primary government. (See GASB 14.)$EXPL$
WHERE id = 3244;

