-- Q3307: Fix #9
UPDATE questions SET
  stem = $EXPL$Baxter Corp.''s defined benefit pension plan incurred $320,000 in service cost during 2025. Following ASU 2017-07, the controller must determine the proper income statement classification for this component., where is service cost reported on the income statement?$EXPL$,
  explanation = $EXPL$Service cost is the only component of net periodic pension cost that must be reported as an operating expense, within the same line items as other employee compensation costs. All other components (interest cost, expected return, amortizations) may be reported outside of operating income or in a separate line. (See ASC 715.)$EXPL$
WHERE id = 3307;

-- Q3326: Fix #9
