-- Q3358: Fix #9
UPDATE questions SET
  stem = $EXPL$A construction equipment manufacturer allows a customer to pay $500,000 two years after delivery of a machine with a cash price of $460,000., a significant financing component exists when:$EXPL$,
  explanation = $EXPL$A significant financing component exists when the timing of payment (either advance or deferred) provides a significant financing benefit to either party. If payment is made well before or well after transfer of goods/services, the transaction price is adjusted for the time value of money. A practical expedient applies if the gap is one year or less. (See ASC 606.)$EXPL$
WHERE id = 3358;

-- Q3359: Fix #9
UPDATE questions SET
  stem = $EXPL$An entity grants a customer a right of return. The estimated return rate is 8% of $5,000,000 in sales. The cost of the products is 60% of selling price., the refund liability is:$EXPL$,
  explanation = $EXPL$Refund liability = Expected returns x Selling price = 8% x $5,000,000 = $400,000. The entity also records an asset for the right to recover returned products at $400,000 x 60% = $240,000 (the cost). Revenue is recognized at $5,000,000 - $400,000 = $4,600,000. (See ASC 606.)$EXPL$
WHERE id = 3359;

