-- Q3375: Fix #9
UPDATE questions SET
  stem = $EXPL$, a derivative must be designated as a hedge at inception. If an entity fails to designate at inception, it:$EXPL$,
  explanation = $EXPL$Hedge accounting requires formal designation and documentation at inception of the hedge relationship. If the entity fails to designate at inception, hedge accounting cannot be applied retroactively. All changes in the derivative's fair value are recognized in current earnings without any deferral in OCI or adjustment to the hedged item. (See ASC 815.)$EXPL$
WHERE id = 3375;

-- Q3378: Fix #9
