-- Q3391: Fix #9
UPDATE questions SET
  stem = $EXPL$Trident Manufacturing sells its production facility to Greystone Realty for $4.2 million and immediately leases it back. The building''s fair value is $5.0 million., a sale-leaseback at below-market terms requires:$EXPL$,
  explanation = $EXPL$When the sale price is below fair value in a sale-leaseback, the difference between fair value and sale price is treated as a prepayment of rent by the seller-lessee (a prepaid lease asset). The leaseback payments are below market to compensate. The seller-lessee does not recognize a loss on the below-market sale. (See ASC 842.)$EXPL$
