-- Q3397: Fix #9
UPDATE questions SET
  stem = $EXPL$Kensington Corp.''s defined benefit pension plan reports the following at December 31, 2025: PBO of $8,000,000, ABO of $7,200,000, and fair value of plan assets of $7,600,000., the funded status reported on the balance sheet is:$EXPL$,
  explanation = $EXPL$Funded status = Plan assets - PBO = $7,600,000 - $8,000,000 = -$400,000 (underfunded). The PBO (not ABO) is used to determine the funded status reported on the balance sheet. The plan is underfunded by $400,000, which is reported as a net pension liability. (See ASC 715.)$EXPL$
WHERE id = 3397;

-- Q3398: Fix #9
UPDATE questions SET
  stem = $EXPL$The actuary for Weston Manufacturing''s defined benefit pension plan used a 5.25% discount rate to measure the projected benefit obligation at the prior year-end. Market interest rates have shifted since then., the discount rate assumption for measuring the PBO should be reassessed:$EXPL$,
  explanation = $EXPL$The discount rate must be reassessed at each measurement date (typically year-end) to reflect current yields on high-quality corporate bonds with durations matching the expected benefit payments. Changes in the discount rate create actuarial gains or losses recognized in OCI. (See ASC 715.)$EXPL$
WHERE id = 3398;

-- Q3401: Fix #9
