-- Q4164: Fix #9
UPDATE questions SET
  stem = $EXPL$A C corporation shareholder borrows $300,000 from the corporation at 1% interest when the AFR is 5%., what is the annual forgone interest?$EXPL$,
  explanation = $EXPL$Under IRC Sec. 7872(a), below-market loans between a corporation and its shareholders require imputation of forgone interest at the applicable federal rate (AFR). Forgone interest equals AFR interest ($300,000 x 5% = $15,000) minus actual interest ($300,000 x 1% = $3,000), totaling $12,000. This amount is treated as a constructive dividend to the shareholder under Sec. 301 and a deemed interest payment back to the corporation. Unlike arm's-length loans at or above the AFR, below-market loans trigger both dividend and interest income consequences under Sec. 7872. (See Section 7872.)$EXPL$
WHERE id = 4164;

