-- Q4365: Fix #9
UPDATE questions SET
  stem = $EXPL$A taxpayer sells property on the installment method and later disposes of the installment obligation by gift., what happens?$EXPL$
WHERE id = 4365;

-- Q4366: Fix #9
UPDATE questions SET
  stem = $EXPL$A taxpayer's business equipment (basis $50,000) is stolen. The taxpayer receives $75,000 in insurance proceeds and purchases replacement equipment for $70,000., how much gain is recognized?$EXPL$,
  explanation = $EXPL$Under IRC Sec. 1033(a)(2), gain from an involuntary conversion is recognized only to the extent that insurance proceeds exceed the cost of qualifying replacement property. The realized gain is $75,000 − $50,000 = $25,000. Because the taxpayer reinvested $70,000 of the $75,000 proceeds, only $5,000 was not reinvested, and gain recognized is limited to that $5,000. The remaining $20,000 of gain is deferred. Unlike a voluntary sale under Sec. 1001, which requires full gain recognition, Sec. 1033 provides mandatory deferral when proceeds are fully reinvested. (See Section 1033.)$EXPL$
WHERE id = 4366;

