-- Q4881: Fix #4, #9
UPDATE questions SET
  cognitive_level = 3,
  stem = $EXPL$Pulse Corp. has a finite-lived customer relationship intangible with a carrying amount of $800,000. Expected future undiscounted cash flows are $750,000, and the fair value is $600,000. The impairment loss is:$EXPL$,
  explanation = $EXPL$Step 1 (recoverability test): Carrying amount ($800,000) exceeds undiscounted cash flows ($750,000), so the asset is impaired. Step 2 (measurement): Impairment loss = Carrying amount − Fair value = $800,000 − $600,000 = $200,000. The asset is written down to its fair value of $600,000. (See ASC 360.)$EXPL$
WHERE id = 4881;

