-- Q11621: Fix #9
UPDATE questions SET
  stem = $EXPL$In September 2025, Drake Electronics repurchases 50,000 shares of its own common stock on the open market for $1.2 million under an authorized buyback program., this repurchase is classified as which type of activity on the statement of cash flows?$EXPL$
